style.css:
@-moz-document domain("capcut.com") {
/* ─── YOUR DARK PURPLE & SPACE THEME ─── */
  :root {
    --bg-darker: #05020a;          /* Deepest black-purple for main background */
    --bg-main: #0c0514;            /* Dark purple-black for editor panels */
    --bg-lighter: #160d24;         /* Lighter purple for sidebars and timeline */
    --accent-color: #8a2be2;       /* Vibrant neon purple for buttons and selections */
    --accent-hover: #a04ef6;       /* Slightly lighter purple for hovering over buttons */
    --text-main: #ffffff;          /* Pure white for readable text */
    --text-muted: #bda8d6;         /* Soft lavender for subtext */
    
    /* Star background effect using CSS gradients */
    --star-pattern: 
      radial-gradient(1px 1px at 20px 30px, #fff, rgba(0,0,0,0)),
      radial-gradient(1px 1px at 40px 70px, #fff, rgba(0,0,0,0)),
      radial-gradient(1px 1px at 50px 160px, #fff, rgba(0,0,0,0)),
      radial-gradient(1.5px 1.5px at 80px 120px, #fff, rgba(0,0,0,0)),
      radial-gradient(1px 1px at 110px 40px, #fff, rgba(0,0,0,0)),
      radial-gradient(2px 2px at 150px 190px, #fff, rgba(0,0,0,0)),
      radial-gradient(1px 1px at 200px 80px, #fff, rgba(0,0,0,0));
    --star-size: 250px 250px;
  }

  /* ─── APPLYING THE THEME TO CAPCUT'S INTERFACE ─── */
  
  /* Main background with space stars */
  body, 
  [class*="layout"], 
  [class*="container"], 
  [class*="editor"] {
    background-color: var(--bg-main) !important;
    background-image: var(--star-pattern) !important;
    background-size: var(--star-size) !important;
    color: var(--text-main) !important;
  }

  /* Timeline, tracks, panels, and sidebars */
  [class*="timeline"], 
  [class*="sidebar"], 
  [class*="panel"], 
  [class*="track"] {
    background-color: var(--bg-lighter) !important;
    background-image: var(--star-pattern) !important;
    background-size: var(--star-size) !important;
    border-color: var(--accent-color) !important;
  }

  /* Top header and navigation bars */
  [class*="header"], 
  [class*="nav"] {
    background-color: var(--bg-darker) !important;
    border-bottom: 1px solid var(--accent-color) !important;
  }

  /* Dark Purple & Glowing Buttons */
  [class*="btn-primary"], 
  [class*="active"], 
  [class*="selected"],
  button[type="submit"] {
    background-color: var(--accent-color) !important;
    color: #ffffff !important;
    box-shadow: 0 0 8px rgba(138, 43, 226, 0.6) !important;
  }

  /* Hover states for buttons */
  [class*="btn-primary"]:hover,
  button:hover {
    background-color: var(--accent-hover) !important;
  }
  
  /* Text adjustments */
  span[class*="desc"], 
  div[class*="subtitle"],
  [class*="muted"] {
    color: var(--text-muted) !important;
  }
}
